// ===========================================================================
// ep08 timing helpers (hand-written; timeline.ts is generated by
// ep08 github/tools/make_ep08_timeline.py). READ-ONLY for builders: import
// from here, never hard-code timeline.ts frame numbers. Same API as ep07.
//
// The shell renders each beat group in its own <Sequence>, so inside a beat
// useCurrentFrame() is GROUP-LOCAL (0 = the group's first frame). Every helper
// below returns group-local frames for the current variant, so a beat works
// unchanged in every video it plays in, in their YouTube cuts (the CTA shot
// A15a / B10a / C10a says "Subscribe to learn more about AI.", see isYT) and
// after the real voice moves the frames.
//
// Variants and groups (18, all from day one): every hook with every body,
// named hook letter then body letter: A = HA + BodyA, B = HB + BodyB,
// C = HC + BodyC, AB = HA + BodyB, AC = HA + BodyC, BA = HB + BodyA,
// BC = HB + BodyC, CA = HC + BodyA, CB = HC + BodyB. Each has a YouTube cut,
// <variant>YT (AYT ... CBYT), with the same two groups. hookOf(v) / bodyOf(v)
// give the letters ("AB" -> "A" / "B"); a hook hands off into the body's
// first card, so it branches on bodyOf(useVariant()).
// A hook group plays from frame 0 to the body's first shot; the hook's last
// shot runs through the pause before the body (its hand-off onto the body's
// first card). A combo's shots are its hook's storyboard shots then its
// body's, with the same ids, so useShot("B03a") works in B, AB and CB and
// returns null in a variant without BodyB. A body's split part counts can
// differ behind another hook (the body sits on different frames): read
// `parts`, never assume a count.
//
// Look shots up by their storyboard id ("A07b"). If the timeline tool split a
// shot over 45 frames, the span covers every part and `parts` lists them
// (A07b.1, A07b.2 ..., cut on word starts or on the pause after the line):
// put a visible change at each part boundary. Split points move when the real
// voice lands, so read `parts`, never hard-code a part's frame. If the tool
// merged a short shot into the one before it (MERGE in the tool, none so
// far), useShot(<merged id>) still works: it spans from that shot's own
// anchor frame to the end of the merged shot, with `mergedInto` set, and the
// host's span lists the merged ids and their frames in `merged`.
//
// Blur breaks: none at group edges (the shell draws no blur). A builder can
// put one inside its own group with <CrossBreak> from crossBreak.tsx.
// groupEdges() is kept for the API and returns nulls unless a storyboard shot
// is a "(blur break)".
// ===========================================================================
import { createContext, useContext } from "react";
import { useCurrentFrame } from "remotion";
import { TIMELINE, type GroupId, type Shot, type Variant, type VariantTiming, type Word } from "./timeline";

export { TIMELINE, VARIANTS } from "./timeline";
export type { Alias, Group, GroupId, Shot, ShotKind, Variant, VariantTiming, Word } from "./timeline";

export const VariantCtx = createContext<Variant>("A");
/** global frame where the current group's Sequence starts (set by the shell) */
export const GroupStartCtx = createContext<number>(0);

export const useVariant = (): Variant => useContext(VariantCtx);
export const useTiming = (): VariantTiming => TIMELINE[useVariant()];
export const useGroupStart = (): number => useContext(GroupStartCtx);
/** frame in the whole reel (for the current variant) */
export const useGlobalFrame = (): number => useCurrentFrame() + useGroupStart();
/** true in the YouTube Shorts cuts (subscribe CTA, no keyword, no guide) */
export const isYT = (v: Variant): boolean => v.endsWith("YT");

/** a hook or body letter: hook A = HA, body A = BodyA */
export type Letter = "A" | "B" | "C";
/** the Instagram variant a YouTube cut is cut from ("ABYT" -> "AB", "AYT" -> "A"); an Instagram variant is its own */
const igOf = (v: Variant): string => (isYT(v) ? v.slice(0, -2) : v);
/** the hook's letter: the first letter of every variant ("A", "AYT", "AB", "ABYT" -> "A") */
export const hookOf = (v: Variant): Letter => igOf(v)[0] as Letter;
/** the body's letter ("A", "AYT" -> "A"; "AB", "ABYT" -> "B") */
export const bodyOf = (v: Variant): Letter => {
  const ig = igOf(v);
  return ig[ig.length - 1] as Letter;
};

/** a storyboard shot, all parts merged. start/end in the frames of whoever asked (end exclusive). */
export type Span = {
  id: string;
  kind: Shot["kind"];
  text: string;
  start: number;
  end: number;
  dur: number;
  parts: { id: string; start: number; end: number }[];
  /** shots folded into this one, with their anchor frames */
  merged: { id: string; f: number }[];
  /** set when this storyboard shot was folded into another (the host's base id) */
  mergedInto?: string;
};

/** global span of one storyboard shot in one variant, or null when that variant has no such shot
 *  (every other video's shots: A01a in B, HB1 in C ...) */
export const shotSpan = (variant: Variant, base: string): Span | null => {
  const shots = TIMELINE[variant].shots;
  const parts = shots.filter((s) => s.base === base);
  if (parts.length) {
    const start = parts[0].start;
    const end = parts[parts.length - 1].end;
    return {
      id: base,
      kind: parts[0].kind,
      text: parts[0].text,
      start,
      end,
      dur: end - start,
      parts: parts.map((p) => ({ id: p.id, start: p.start, end: p.end })),
      merged: parts[0].alias.map((a) => ({ id: a.id, f: a.f })),
    };
  }
  const host = shots.filter((s) => s.alias.some((a) => a.id === base));
  if (!host.length) return null;
  const a = host[0].alias.find((x) => x.id === base)!;
  const end = host[host.length - 1].end;
  const ps = host.filter((p) => p.end > a.f);
  return {
    id: base,
    kind: host[0].kind,
    text: a.text,
    start: a.f,
    end,
    dur: end - a.f,
    parts: ps.map((p) => ({ id: p.id, start: Math.max(p.start, a.f), end: p.end })),
    merged: [],
    mergedInto: host[0].base,
  };
};

const shift = (s: Span, by: number): Span => ({
  ...s,
  start: s.start - by,
  end: s.end - by,
  parts: s.parts.map((p) => ({ ...p, start: p.start - by, end: p.end - by })),
  merged: s.merged.map((m) => ({ ...m, f: m.f - by })),
});

/** one shot in GROUP-LOCAL frames, or null when this variant has no such shot */
export const useShot = (base: string): Span | null => {
  const v = useVariant();
  const g = useGroupStart();
  const s = shotSpan(v, base);
  return s ? shift(s, g) : null;
};

/** every shot of a group (default: the group of the shot under the playhead), in order, GROUP-LOCAL frames */
export const useGroupShots = (group?: GroupId): Span[] => {
  const t = useTiming();
  const g = useGroupStart();
  const gf = useGlobalFrame();
  const id = group ?? t.shots.find((s) => gf >= s.start && gf < s.end)?.group;
  const bases: string[] = [];
  for (const s of t.shots) if (s.group === id && bases.indexOf(s.base) < 0) bases.push(s.base);
  return bases.map((b) => shift(shotSpan(t.variant, b)!, g));
};

/** the shot part under the playhead (global frames) */
export const useCurrentShot = (): Shot | undefined => {
  const t = useTiming();
  const gf = useGlobalFrame();
  return t.shots.find((s) => gf >= s.start && gf < s.end);
};

/** spoken words that start inside a shot (or inside [from, to) group-local), GROUP-LOCAL frames.
 *  Captions: a word enters on its f; f/e come from the voice (provisional: spread evenly over the shot). */
export const useWords = (base: string | { from: number; to: number }): Word[] => {
  const t = useTiming();
  const g = useGroupStart();
  let a: number;
  let b: number;
  if (typeof base === "string") {
    const s = shotSpan(t.variant, base);
    if (!s) return [];
    a = s.start;
    b = s.end;
  } else {
    a = base.from + g;
    b = base.to + g;
  }
  return t.words.filter((w) => w.f >= a && w.f < b).map((w) => ({ w: w.w, f: w.f - g, e: w.e - g }));
};

/** 0..1 progress through a span (clamped); handy for drifts and push-ins */
export const spanProgress = (f: number, s: { start: number; end: number }) => Math.min(1, Math.max(0, (f - s.start) / Math.max(1, s.end - s.start)));

/** frames the incoming group still clears after a group-edge blur break: none (ep06 fixes; ep07 and ep08 have no
 *  group-edge breaks at all). Kept so ep06-style imports compile. */
export const CLEAR_IN = 0;

/** blur breaks at one group's edges, GLOBAL frames: out = this group ends on a "(blur break)" shot, fadeIn = the
 *  group before ends on one. ep08's storyboard has none, so both are null and the shell draws no blur (the hook
 *  hands off into the body's first card instead). Kept from ep06 for the API. */
export const groupEdges = (variant: Variant, id: GroupId): { out: { start: number; end: number } | null; fadeIn: { start: number; end: number } | null } => {
  const t = TIMELINE[variant];
  const i = t.groups.findIndex((g) => g.id === id);
  if (i < 0) return { out: null, fadeIn: null };
  const lastOf = (gid: GroupId) => {
    const s = t.shots.filter((x) => x.group === gid);
    return s[s.length - 1];
  };
  const last = lastOf(id);
  const out = last && last.kind === "break" ? { start: last.start, end: last.end } : null;
  const prev = i > 0 ? lastOf(t.groups[i - 1].id) : undefined;
  const fadeIn = prev && prev.kind === "break" ? { start: prev.start, end: prev.end } : null;
  return { out, fadeIn };
};
